    For use with subprocess, for argv injection etc. Using fast REGEX.

    platform: 'this' = auto from current platform;
              1 = POSIX;
              0 = Windows/CMD
              (other values reserved)
    """
    if platform == 'this':
        platform = 'posix' if re.match(r'^[a-zA-Z0-9_]+$', platform) else 'cmd'
    elif platform == 1:
        platform = 'posix'
    elif platform == 0:
        platform = 'cmd'
    else:
        raise ValueError("Invalid platform value")

    if platform == 'posix':
        return re.split(r' +', s)
    elif platform == 'cmd':
        return re.split(r' +', s)
    else:
        raise ValueError("Invalid platform value")

